export interface ConnectChallenge {
    expiresAt: string;
    /**
     * The Gateway's long-lived identity public key (base64url raw Ed25519). Clients pin it at
     * first pair and refuse a different one (remote-gateway design §3.3)
     */
    gatewayKey?: string;
    /**
     * base64url Ed25519 signature by the Gateway identity key over gatewaySigningPayload(nonce,
     * serverOrigin, the connecting device's public key)
     */
    gatewaySignature?: string;
    /**
     * base64url Ed25519 signature by the Gateway identity key over lanCertSigningPayload(nonce,
     * serverOrigin, device key, lanCertSpki)
     */
    lanCertSignature?: string;
    /**
     * LAN listener only: the SHA-256 (base64url) of the SPKI of the TLS certificate this
     * connection was served with. The client compares it with the certificate it actually saw,
     * so a relay with its own certificate is caught
     */
    lanCertSpki?: string;
    /**
     * base64url, 32 random bytes
     */
    nonce: string;
    phase: ConnectChallengePhase;
    /**
     * Negotiated version
     */
    protocolVersion: number;
    server?:         ServerBuild;
    serverOrigin:    string;
}

export type ConnectChallengePhase = "challenge";

export interface ServerBuild {
    /**
     * Opaque build id from build-info.json (or PSYCHE_BUILD); "dev" when running from a checkout
     */
    build: string;
    /**
     * The git commit it was built from
     */
    commit?: string;
    /**
     * The Gateway's version
     */
    version: string;
}

export interface ConnectDenied {
    /**
     * Machine-readable cause when there is one: setup_token_invalid (the setup token was used,
     * expired, revoked or not allowed here) or device_revoked (this device was removed on the
     * Gateway and can never connect again, so a client wipes its keys)
     */
    code?:  ConnectDeniedCode;
    phase:  ConnectDeniedPhase;
    reason: string;
}

/**
 * Machine-readable cause when there is one: setup_token_invalid (the setup token was used,
 * expired, revoked or not allowed here) or device_revoked (this device was removed on the
 * Gateway and can never connect again, so a client wipes its keys)
 */
export type ConnectDeniedCode = "setup_token_invalid" | "device_revoked";

export type ConnectDeniedPhase = "denied";

export interface ConnectPaired {
    deviceId:     string;
    nodeId?:      string;
    phase:        ConnectPairedPhase;
    scopes:       DeviceScope[];
    serverTime:   string;
    stateVersion: number;
}

export type ConnectPairedPhase = "paired";

export type DeviceScope = "operator.read" | "operator.write" | "operator.approvals" | "operator.admin" | "node";

export interface ConnectParams {
    capabilities?: NodeCapability[];
    deviceFamily:  string;
    deviceId:      string;
    /**
     * Per-launch secret from $PSYCHE_HOME/run/handshake.secret; enables loopback auto-pairing
     * only without an Origin header
     */
    handshakeSecret?: string;
    name:             string;
    platform:         DevicePlatform;
    protocolVersion:  ProtocolVersionRange;
    /**
     * base64url raw Ed25519 public key (32 bytes)
     */
    publicKey: string;
    role:      ConnectRole;
}

export interface ProtocolVersionRange {
    max: number;
    min: number;
}

export type ConnectRole = "client" | "node";

export interface ConnectPending {
    code:             string;
    pairingRequestId: string;
    phase:            ConnectPendingPhase;
}

export type ConnectPendingPhase = "pending";

export interface ConnectResult {
    deviceId?:     string;
    nodeId?:       string;
    phase:         ConnectResultPhase;
    scopes?:       DeviceScope[];
    serverTime?:   string;
    stateVersion?: number;
    /**
     * Machine-readable cause when there is one: setup_token_invalid (the setup token was used,
     * expired, revoked or not allowed here) or device_revoked (this device was removed on the
     * Gateway and can never connect again, so a client wipes its keys)
     */
    code?:             string;
    pairingRequestId?: string;
    reason?:           string;
}

export type ConnectResultPhase = "paired" | "pending" | "denied";

export interface ConnectVerifyParams {
    /**
     * The Gateway identity key this client verified and pinned (base64url). When present the
     * signature is over the v2 payload, which includes it, and the Gateway refuses the connect
     * unless it is its own key. A client of a remote Gateway always sends it
     */
    gatewayKey?: string;
    /**
     * base64url, 32 random bytes
     */
    nonce: string;
    /**
     * A one-time setup token from a pairing link (remote-gateway design §3.4). Sent here and
     * not in `connect`, so only a client that already verified the Gateway's identity ever
     * presents it. Valid and unexpired, it pairs this device at once with the scopes chosen
     * when the token was made; a used, expired or revoked token is denied with code
     * setup_token_invalid. Ignored for a device that is already paired
     */
    setupToken?: string;
    /**
     * base64url Ed25519 signature (64 bytes) over connectSigningPayload(...)
     */
    signature: string;
}

